// The booster packs the card shop sells, in release order (the first six core sets so far). Their card lists and
// rarities come from public/data/boosters.json (data/boosters.json, generated by build-pool); here only what the shop
// adds: the price (placeholders) and the colour of the set's display box.

export interface BoosterStock {
  /** Set code; also the picture's name (public/boosters/<code>.png, `npm run build-boosters`). */
  code: string;
  /** In chips. */
  price: number;
  /** The display box's cardboard, picked from the pack's art. */
  color: number;
}

/** Every core booster of the era has 9 cards a pack. */
export const CARDS_PER_PACK = 9;

export const BOOSTERS: BoosterStock[] = [
  { code: "LOB", price: 50, color: 0x2b7cc0 },
  { code: "MRD", price: 50, color: 0x7a808c },
  { code: "SRL", price: 50, color: 0x2e8a52 },
  { code: "PSV", price: 60, color: 0xb83a2e },
  { code: "LON", price: 60, color: 0x5e3d78 },
  { code: "LOD", price: 60, color: 0x3d5a78 },
];

/** A set's entry in public/data/boosters.json: each card is [number, passcode, rarity]. */
export interface BoosterList {
  code: string;
  name: string;
  /** TCG release date, YYYY-MM-DD. */
  released: string;
  cards: [string, number, string][];
}

/** A rarity's chip in the shop (label, colour) and how big a show its reveal makes (0 none ... 4 the most); highest first. */
export const RARITIES: [string, { label: string; color: number; tier: number }][] = [
  ["Secret Rare", { label: "SCR", color: 0xb0409a, tier: 4 }],
  ["Ultra Rare", { label: "UR", color: 0xc9952a, tier: 3 }],
  ["Super Rare", { label: "SR", color: 0x2f8fbf, tier: 2 }],
  ["Rare", { label: "R", color: 0x6a7f98, tier: 1 }],
  ["Super Short Print", { label: "SSP", color: 0x7a6a58, tier: 0 }],
  ["Short Print", { label: "SP", color: 0x8a7a68, tier: 0 }],
  ["Common", { label: "C", color: 0x9a9488, tier: 0 }],
];
export const rarityLook = (rarity: string) => RARITIES.find(([r]) => r === rarity)?.[1] ?? RARITIES[RARITIES.length - 1][1];

/**
 * The rare slot, roughly the era's odds: a Secret Rare 1 pack in 24, an Ultra Rare 1 in 12, a Super Rare 1 in 6, else
 * a Rare. A set without the rarity drawn gives the next lower one.
 */
const RARE_SLOT: [string, number][] = [["Secret Rare", 1 / 24], ["Ultra Rare", 1 / 12], ["Super Rare", 1 / 6], ["Rare", 1]];
/** The other slots: a Short Print turns up half as often as a Common, a Super Short Print a quarter as often. */
const COMMON_WEIGHT: Record<string, number> = { Common: 4, "Short Print": 2, "Super Short Print": 1 };

export interface Pull {
  code: number;
  rarity: string;
}

/** One pack of `list`: `size` - 1 different commons and one card from the rare slot, in random order. */
export function pullPack(list: BoosterList, size = CARDS_PER_PACK, random = Math.random): Pull[] {
  const cards = list.cards.map(([, code, rarity]) => ({ code, rarity }));
  let roll = random(), slot = RARE_SLOT.length - 1;
  for (let i = 0, acc = 0; i < RARE_SLOT.length; i++) {
    acc += RARE_SLOT[i][1];
    if (roll < acc) { slot = i; break; }
  }
  let rares: Pull[] = [];
  for (let i = slot; i < RARE_SLOT.length && !rares.length; i++) rares = cards.filter((c) => c.rarity === RARE_SLOT[i][0]);
  const pack = rares.length ? [rares[Math.floor(random() * rares.length)]] : [];

  const commons = cards.filter((c) => c.rarity in COMMON_WEIGHT);
  while (pack.length < size && commons.length) {
    const total = commons.reduce((n, c) => n + COMMON_WEIGHT[c.rarity], 0);
    roll = random() * total;
    let i = 0;
    while (i < commons.length - 1 && (roll -= COMMON_WEIGHT[commons[i].rarity]) >= 0) i++;
    pack.push(commons.splice(i, 1)[0]);
  }
  for (let i = pack.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [pack[i], pack[j]] = [pack[j], pack[i]];
  }
  return pack;
}
